1	import { createContext, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
2	import { useAccount } from "../auth/Account.tsx";
3	import { markPackSync } from "../storage/db.ts";
4	import { syncBus } from "./bus.ts";
5	import { createApi } from "./client.ts";
6	import { apiBase, setSyncEnabled, syncEnabled } from "./config.ts";
7	import { openLive, socketUrl, type LiveSocket } from "./socket.ts";
8	import { lastActive } from "../run/active.ts";
9	import { createEngine, storageDb, type Engine, type Report, type SyncStatus } from "./engine.ts";
10	
11	/**
12	 * Sync, as the app sees it.
13	 *
14	 * Available only where all three are true: there is an API (a hosted build
15	 * with a client id), somebody is signed in, and this device's switch has
16	 * not been turned off. Anywhere else, disk, the public page, a player who
17	 * has not signed in or who switched this device off, the provider renders
18	 * its children and nothing else, so the rest of the app never has to ask
19	 * twice.
20	 *
21	 * When it is on, a pass runs at sign-in, when the tab comes back, when the
22	 * network does, and two seconds after the last local change. While this
23	 * device has a run open it also holds a socket to the server, hidden tab
24	 * or not, that says "changed" when another device moves, and syncs at
25	 * once; a poll every ten seconds stands in while the socket is down, and
26	 * every minute as a backstop while it is up.
27	 */
28	
29	export interface Sync {
30	  /** There is an API and an account; the switch may be turned on. */
31	  available: boolean;
32	  enabled: boolean;
33	  setEnabled: (on: boolean) => void;
34	  status: "off" | SyncStatus;
35	  last: Report | null;
36	  syncNow: () => void;
37	  setPackSync: (id: string, on: boolean) => Promise<void>;
38	  /**
39	   * Pass a gesture to everyone watching a run.
40	   *
41	   * Answers whether it went. For dice in the air the answer does not
42	   * matter and is ignored; for handing a setup out it is the difference
43	   * between telling somebody it happened and telling them the truth.
44	   */
45	  gesture: (id: string, kind: string, data?: Record<string, unknown>) => boolean;
46	  /** The verdict on a deck's press, back to the one deck that made it, with the run's `seq` where there is a fresh one. */
47	  drove: (to: string, ref: string, ok: boolean, say?: string, seq?: number) => void;
48	}
49	
50	const off: Sync = {
51	  available: false,
52	  enabled: false,
53	  setEnabled: () => {},
54	  status: "off",
55	  last: null,
56	  syncNow: () => {},
57	  setPackSync: async () => {},
58	  gesture: () => false,
59	  drove: () => {},
60	};
61	
62	export const SyncContext = createContext<Sync>(off);
63	
64	export function useSync(): Sync {
65	  return useContext(SyncContext);
66	}
67	
68	const SETTLE_MS = 2000;
69	/** How often an open run asks after the others when nothing else will tell it. */
70	const POLL_MS = 10_000;
71	/** …and when the socket is up and would say so: a backstop, not the mechanism. */
72	const POLL_WITH_SOCKET_MS = 60_000;
73	
74	export function SyncProvider({ children }: { children: ReactNode }) {
75	  const account = useAccount();
76	  const base = apiBase();
77	  const available = base !== undefined && account.status === "signed-in";
78	
79	  // The account's address, told to the server on sign-in rather than only
80	  // from the profile page: an invitation is checked against it.
81	  useEffect(() => {
82	    if (!base || account.status !== "signed-in" || !account.user.email) return;
83	    void createApi(base, account.getAccessToken)
84	      .putProfile({ email: account.user.email })
85	      .catch(() => {});
86	    // Once per sign-in.
87	    // eslint-disable-next-line react-hooks/exhaustive-deps
88	  }, [base, account.status === "signed-in" ? account.user.id : null]);
89	
90	  const [enabled, setEnabledState] = useState(() => syncEnabled());
91	  const [status, setStatus] = useState<Sync["status"]>("off");
92	  const [last, setLast] = useState<Report | null>(null);
93	  /** The open socket, for gestures sent from the run view. */
94	  const socketRef = useRef<LiveSocket | null>(null);
95	  const engineRef = useRef<Engine | null>(null);
96	
97	  const active = available && enabled;
98	
99	  useEffect(() => {
100	    if (!active || account.status !== "signed-in" || !base) {
101	      engineRef.current = null;
102	      setStatus("off");
103	      return;
104	    }
105	    let live = true;
106	    let settle: ReturnType<typeof setTimeout> | undefined;
