9	  type Changed,
10	  type Drive,
11	  type Gesture,
12	} from "./socket.ts";
13	
14	/**
15	 * A pretend socket: opened, closed and spoken to by the test, so the
16	 * reconnect and re-watch can be watched without a network.
17	 */
18	class FakeSocket {
19	  static all: FakeSocket[] = [];
20	  sent: string[] = [];
21	  closed = false;
22	  onopen: (() => void) | null = null;
23	  onmessage: ((e: { data: unknown }) => void) | null = null;
24	  onclose: (() => void) | null = null;
25	  onerror: (() => void) | null = null;
26	  constructor(public url: string) {
27	    FakeSocket.all.push(this);
28	  }
29	  send(data: string) {
30	    this.sent.push(data);
31	  }
32	  close() {
33	    this.closed = true;
34	    this.onclose?.();
35	  }
36	}
37	
38	/** Waits that a test releases by hand, in order. */
39	function manualClock() {
40	  const pending: Array<{ ms: number; fn: () => void }> = [];
41	  return {
42	    pending,
43	    wait: (ms: number, fn: () => void) => {
44	      const entry = { ms, fn };
45	      pending.push(entry);
46	      return () => {
47	        const i = pending.indexOf(entry);
48	        if (i >= 0) pending.splice(i, 1);
49	      };
50	    },
51	    fire() {
52	      const next = pending.shift();
53	      next?.fn();
54	    },
55	  };
56	}
